311	        MutationResponse rev2 = service.review(
312	                new ReviewRequest("st", 1, 1L, "req-" + rid("review")));
313	        assertTrue(dataOf(rev2).current());
314	        assertEquals("CLEAR", service.getCurrentReview("st").conclusion());
315	
316	        // 航线替换后再次 STALE
317	        service.replaceRoute(new RouteReplaceRequest(
318	                "st", 1, pts(0, 10, 100, 10), "req-" + rid("replace")));
319	        assertEquals("STALE", service.getCurrentReview("st").conclusion());
