            sql.append("(?, ?, ?)");
        }
        sql.append(") GROUP BY p.cell_x, p.cell_y, p.bucket_start");
        Object[] args = new Object[bucketKeys.size() * 3];
        for (int i = 0; i < bucketKeys.size(); i++) {
            int[] key = intKeys.get(i);
            args[3 * i] = key[0];
            args[3 * i + 1] = key[1];
            args[3 * i + 2] = bucketKeys.get(i);
        }
        return jdbc.query(sql.toString(),
                (rs, n) -> new Object[]{rs.getInt(1), rs.getInt(2), rs.getLong(3), rs.getInt(4)},
                args);
    }
}

