// 全量占用前后态：以数据库给出的全量基线为基础，按参与航线前后序列重算
Map<BucketSlot, int[]> participantCount = new HashMap<>();
for (BucketSlot bucket : outcome.affectedBuckets) {
    int base = baselineUsed.getOrDefault(bucket, 0);
    outcome.usedBefore.put(bucket, base);
    outcome.usedAfter.put(bucket, base);
    participantCount.put(bucket, new int[2]);
}
// 参与航线基线占用需要从全量基线中扣除后再按后态加回，
// 因此基线统计采用“全量”值；这里修正：参与航线在 before/after 中的计数
for (List<PlanSlotPo> before : beforePlans.values()) {
    for (PlanSlotPo slot : before) {
        participantCount.get(new BucketSlot(slot.cellX(), slot.cellY(), slot.bucketStart()))[0]++;
    }
}
for (List<PlanSlotPo> after : outcome.afterPlans.values()) {
    for (PlanSlotPo slot : after) {
        participantCount.get(new BucketSlot(slot.cellX(), slot.cellY(), slot.bucketStart()))[1]++;
